        &::before {
          content: '▸';
          font-size: 0.85em;
          transition: transform 0.15s ease;
        }
      }

      &[open] summary.mathbox-header {
        margin-bottom: 0.5rem;

        &::before {
          transform: rotate(90deg);
        }
